# define ICMP6_FILTER_WILLBLOCK(type, filterp) ((((filterp)->icmp6_filt[(type) >> 5]) & (1U << ((type) & 31))) != 0)
# define ICMP6_FILTER_SETPASS(type, filterp) (((filterp)->icmp6_filt[(type) >> 5]) &= ~(1U << ((type) & 31)))
